CREATE OR REPLACE FUNCTION public.set_student_game_courses(_user uuid,_courses uuid[],_all boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'Apenas professores e gestores'; END IF; IF cardinality(_courses)>500 THEN RAISE EXCEPTION 'Seleção inválida'; END IF; INSERT INTO public.student_game_access(user_id,all_courses) VALUES(_user,_all) ON CONFLICT(user_id) DO UPDATE SET all_courses=excluded.all_courses; DELETE FROM public.student_game_courses WHERE user_id=_user; INSERT INTO public.student_game_courses(user_id,course_id) SELECT _user,unnest(_courses) ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.set_student_game_courses(uuid,uuid[],boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_student_game_courses(uuid,uuid[],boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.set_course_question_disciplines(_course uuid,_disciplines text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'Apenas professores e gestores'; END IF; DELETE FROM public.course_question_disciplines WHERE course_id=_course; INSERT INTO public.course_question_disciplines(course_id,discipline_key) SELECT _course,unnest(_disciplines) ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.set_course_question_disciplines(uuid,text[]) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_course_question_disciplines(uuid,text[]) TO authenticated;